mapper.select:
select e.*, d.name deptName
from emp as e
         left join dept as d on e.dept_id = d.id


        and e.name like concat('%', #{empQueryParam.name}, '%')


        and e.gender = #{empQueryParam.gender}


        and e.entry_date >= #{empQueryParam.begin}


        and e.entry_date <= #{empQueryParam.end}


limit #{start}, #{empQueryParam.pageSize}
